#[test]
fn test_a_node_is_the_image_it_is_or_says_why_not() {
    let res: &mut crate::port::Cells = &mut crate::port::Cells::new();
    at_geo(res, 0);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 0, "a figure that is one whole image gets it (asset 0)");
    crate::testport::assert_eq(crate::port::cells_at(res, 3), nz_part(), "a figure inside one image's box is part of it");
    crate::testport::assert_eq(crate::port::cells_at(res, 5), nz_composite(), "a figure over two images is a composite");
    crate::testport::assert_eq(crate::port::cells_at(res, 7), nz_vector(), "a figure with no image under it is vector");
    crate::testport::assert_eq(crate::port::cells_at(res, 9), nz_withheld(), "a signature seal is withheld");
    crate::testport::assert_eq(crate::port::cells_at(res, 10), -1, "a digital signature has no pixels and no field");
    crate::testport::assert_eq(crate::port::cells_at(res, 11), -1, "no reason either");
    crate::testport::assert_eq(crate::port::cells_at(res, 12), 1, "a stamp seal that is one image gets it (asset 1)");
    crate::testport::assert_eq(crate::port::cells_at(res, 15), nz_part(), "an image the size of a page is never an asset at images");
    crate::testport::assert_eq(crate::port::cells_at(res, 17), nz_vector(), "a node with no region is vector");
    // with asset-signatures on, the signature seal is the image
    at_geo(res, 1);
    crate::testport::assert_eq(crate::port::cells_at(res, 8), 0, "a signature seal gets the image when signatures are on");
    crate::testport::assert_eq(crate::port::cells_at(res, 9), -1, "and has no reason");
}
