    crate::testport::assert_eq(node_parent(nn, 4), 1, "inside the section");
    crate::testport::assert_eq(node_kind(nn, 5), nk_paragraph(), "the second paragraph");
    crate::testport::assert_eq(node_kind(nn, 6), nk_figure(), "the figure at 50000 ends the section");
    crate::testport::assert_eq(node_parent(nn, 6), 1, "still inside the section");
    crate::testport::assert_eq(node_kind(nn, 7), nk_paragraph(), "the paragraph after the section");
    crate::testport::assert_eq(node_parent(nn, 7), 0, "in the document");
    crate::testport::assert_eq(node_kind(nn, 8), nk_figure(), "the figure after everything");
    crate::testport::assert_eq(node_parent(nn, 8), 0, "is the document's last child");
